-- CatModLangFor42: per-owner translations for keys that several MODs (or a MOD and vanilla) define
-- with different English. JSON ships first; this file runs at shared Lua load (after Translator.loadFiles
-- and ScriptManager.Load) and writes the translation of the active owner that loads last into
-- Translator.BY_NAME. Data: media/CatModLang/variants_<CH|CN>.tsv, generated by scripts/build_mod.py from
-- sources/owner_variants.json. Rules: .claude/skills/modlang-dev/references/variants.md.
-- No non-ASCII literals here: Kahlua truncates them (all text comes from UTF-8 data files).

CatModLang = CatModLang or {}

local MOD_ID = "CatModLangFor42"
local UNESCAPE = { ["\\"] = "\\", t = "\t", n = "\n", r = "\r" }

function CatModLang.unescape(s)
    if not s:find("\\", 1, true) then return s end
    return (s:gsub("\\(.)", UNESCAPE))
end

-- Lines of a file shipped in this pack (nil when missing). Comment lines (#) are skipped.
function CatModLang.readLines(path)
    local r = getModFileReader(MOD_ID, path, false)
    if not r then return nil end
    local lines = {}
    local line = r:readLine()
    while line do
        if line ~= "" and line:sub(1, 1) ~= "#" then lines[#lines + 1] = line end
        line = r:readLine()
    end
    r:close()
    return lines
end

-- Iterative merge sort (stable). Kahlua's table.sort is a recursive quicksort that overflows on a few
-- hundred already-sorted entries; same as the family's sortSafe.
local function less(a, b) return a < b end
function CatModLang.sortSafe(list, comp)
    comp = comp or less
    local n, buf, width = #list, {}, 1
    while width < n do
        for i = 1, n, width * 2 do
            local midEnd, hiEnd = math.min(i + width - 1, n), math.min(i + width * 2 - 1, n)
            local a, b, k = i, midEnd + 1, i
            while a <= midEnd and b <= hiEnd do
                if comp(list[b], list[a]) then buf[k] = list[b]; b = b + 1 else buf[k] = list[a]; a = a + 1 end
                k = k + 1
            end
            while a <= midEnd do buf[k] = list[a]; a = a + 1; k = k + 1 end
            while b <= hiEnd do buf[k] = list[b]; b = b + 1; k = k + 1 end
        end
        for j = 1, n do list[j] = buf[j] end
        width = width * 2
    end
    return list
end

-- Owner of a MOD: workshop id (only for Steam downloads) and mod folder name, as in the census.
function CatModLang.ownerOf(info)
    local root = info and info:getDir():match("([^/\\]+)[/\\]*$")
    if root then return info:getWorkshopID() or "", root end
end

-- owners["<workshop id>/<folder>"] = load order (1..n); local copies have no workshop id ("/<folder>").
-- mods[order] = { id, wid, root, info }. Same order as translation loading (ZomboidFileSystem.getModIDs).
function CatModLang.activeOwners()
    local owners, list, mods = {}, {}, getActivatedMods()
    for i = 0, mods:size() - 1 do
        local id = mods:get(i)
        local info = getModInfoByID(id)
        local wid, root = CatModLang.ownerOf(info)
        if root then
            owners[wid .. "/" .. root] = i + 1
            list[i + 1] = { id = id, wid = wid, root = root, info = info }
        end
    end
    return owners, list
end

-- Load order of the owner written as wid/root in the data files, or nil when not active.
function CatModLang.ownerRank(owners, wid, root)
    return owners[wid .. "/" .. root] or owners["/" .. root]
end

local function apply(lang)
    local byName = Translator.BY_NAME
    if not byName then
        print("[CatModLang] variants skipped: Translator.BY_NAME missing")
        return
    end
    local lines = CatModLang.readLines("media/CatModLang/variants_" .. lang .. ".tsv")
    if not lines then
        print("[CatModLang] variants skipped: variants_" .. lang .. ".tsv missing")
        return
    end
    local owners = CatModLang.activeOwners()
    local best, order = {}, {}
    for _, line in ipairs(lines) do
        local file, key, wid, root, value = line:match("^([^\t]+)\t([^\t]+)\t([^\t]*)\t([^\t]+)\t(.*)$")
        local rank = file and CatModLang.ownerRank(owners, CatModLang.unescape(wid), CatModLang.unescape(root))
        if rank then
            local id = file .. "\t" .. key
            local b = best[id]
            if not b then
                order[#order + 1] = id
                best[id] = { rank = rank, file = file, key = CatModLang.unescape(key), value = value }
            elseif rank > b.rank then
                b.rank, b.value = rank, value
            end
        end
    end
    local scripts = ScriptManager.instance
    local keys, items, recipes = 0, 0, 0
    local descs = {} -- UI text shown before -> after (false = ambiguous), for cached trait/profession descriptions
    local written = {} -- "file<TAB>key" actually written this load (read by the E2E scenario)
    for _, id in ipairs(order) do
        local b = best[id]
        local map = b.value ~= "" and byName:get(b.file)
        if map then
            local value = CatModLang.unescape(b.value)
            local old = b.file == "UI" and not value:find("%", 1, true) and getTextOrNull(b.key)
            map:put(b.key, value)
            keys = keys + 1
            written[b.file .. "\t" .. b.key] = true
            if b.file == "ItemName" then
                local item = scripts:getItem(b.key)
                if item then item:setDisplayName(value); items = items + 1 end
            elseif b.file == "Recipes" then
                local recipe = scripts:getCraftRecipe(b.key)
                if recipe then recipe:overrideTranslationName(value); recipes = recipes + 1 end
            elseif old and old ~= "" and not old:find("%", 1, true) then
                local new = getTextOrNull(b.key)
                if descs[old] == nil then descs[old] = new elseif descs[old] ~= new then descs[old] = false end
            end
        end
    end
    CatModLang.written = written
    -- Trait/profession descriptions are copied from getText at script load, before Lua (names are final).
    -- Vanilla MainCreationMethods appends XP boosts to them at OnGameBoot, after this file.
    local refreshed = 0
    for _, list in ipairs({ CharacterTraitDefinition.getTraits(), CharacterProfessionDefinition.getProfessions() }) do
        for i = 0, list:size() - 1 do
            local def = list:get(i)
            local new = descs[def:getDescription()]
            if new then def:setDescription(new); refreshed = refreshed + 1 end
        end
    end
    print("[CatModLang] variants " .. lang .. ": rows=" .. #lines .. " applied=" .. keys
        .. " items=" .. items .. " recipes=" .. recipes .. " descs=" .. refreshed)
end

local lang = tostring(Translator.getLanguage())
if lang == "CH" or lang == "CN" then
    local ok, err = pcall(apply, lang)
    if not ok then print("[CatModLang] variants failed: " .. tostring(err)) end
end
